program.source:
Algorithm Binary
  Dimension v[10] As Integer;
  For i <- 0 To 9 Do
    Read v[i];
  EndFor
  Define searched As Integer;
  Read searched;
  Define low As Integer <- 0;
  Define high As Integer <- 9;
  Define middle As Integer;
  Define position As Integer <- -1;
  While low <= high And position = -1 Do
    middle <- (low + high) Div 2;
    If v[middle] = searched Then
      position <- middle;
    Else
      If v[middle] < searched Then
        low <- middle;
      Else
        high <- middle - 1;
      EndIf
    EndIf
  EndWhile
  Write position;
EndAlgorithm

